            right = parse_primary()
            return Comparison(op, left, right)
        elif tokens[pos].type == TokenType.KEYWORD and tokens[pos].value == "IS":
            consume(TokenType.KEYWORD)
            if tokens[pos].type == TokenType.KEYWORD and tokens[pos].value == "NOT":
                consume(TokenType.KEYWORD)
                consume(TokenType.KEYWORD)
                return IsNull(left, True)
            elif tokens[pos].type == TokenType.KEYWORD and tokens[pos].value == "NULL":
                consume(TokenType.KEYWORD)
                return IsNull(left, False)
            else:
                raise SQLSyntaxError(f"Unexpected keyword: {tokens[pos].value}")
        else:
            return left

    def parse_not_expr() -> Expr:
        if tokens[pos].type == TokenType.KEYWORD and tokens[pos].value == "NOT":
            consume(TokenType.KEYWORD)
            return Not(parse_not_expr())
